"use strict";(self.webpackChunkchzhshch_blog=self.webpackChunkchzhshch_blog||[]).push([["16466"],{64064(e,n,t){t.r(n),t.d(n,{metadata:()=>o,default:()=>c,frontMatter:()=>r,contentTitle:()=>i,toc:()=>l,assets:()=>h});var o=JSON.parse('{"id":"2002posts/2002poems6","title":"","description":"Dragon seed and flea \u2014 one test and you\'ll know \u2014 once wine-full and rice-full \u2014 here they come to bother again","source":"@site/i18n/en/docusaurus-plugin-content-docs/current/2002posts/2002poems6.md","sourceDirName":"2002posts","slug":"/2002posts/2002poems6","permalink":"/en/2002posts/2002poems6","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"id":"2002poems6","title":"","hide_table_of_contents":true,"sidebar_label":"Collection of 30+ poems by Xiaoren on 7/18 \u2014 is there something wrong with casual chat?"},"sidebar":"y2002postsSidebar","previous":{"title":"Collection of five-character poems composed today from 12 to 3:30 \u2014 Xiaoren talking to himself, please don\'t take it personally","permalink":"/en/2002posts/2002poems5"},"next":{"title":"\\"Playing a long one: 54-rhyme poem responding to garychangguo, Xutang, and others\\"","permalink":"/en/2002posts/longpoem"}}'),s=t(74848),a=t(28453);let r={id:"2002poems6",title:"",hide_table_of_contents:!0,sidebar_label:"Collection of 30+ poems by Xiaoren on 7/18 \u2014 is there something wrong with casual chat?"},i="Collection of 30-Plus Poems Written by Xiaoren on 7.18 \u2014 Is Bantering a Problem?",h={},l=[];function d(e){let n={h1:"h1",header:"header",p:"p",...(0,a.R)(),...e.components};return(0,s.jsxs)(s.Fragment,{children:[(0,s.jsx)(n.header,{children:(0,s.jsx)(n.h1,{id:"collection-of-30-plus-poems-written-by-xiaoren-on-718--is-bantering-a-problem",children:"Collection of 30-Plus Poems Written by Xiaoren on 7.18 \u2014 Is Bantering a Problem?"})}),"\n",(0,s.jsx)(n.p,{children:"Dragon seed and flea \u2014 one test and you'll know \u2014 once wine-full and rice-full \u2014 here they come to bother again"}),"\n",(0,s.jsx)(n.p,{children:"Ascending the hall: Airs, Elegantiae, Hymns \u2014 under the covers: Jin Ping Mei \u2014 Confucius the Second's descendants are thriving \u2014 always occupying the high platform"}),"\n",(0,s.jsx)(n.p,{children:"Fighting tigers with your brothers \u2014 looking east, looking west \u2014 seeing clouds that bear no rain \u2014 another push upward"}),"\n",(0,s.jsx)(n.p,{children:"The four great elements combine by chance \u2014 following karma, each goes east or west \u2014 the tide comes, spring waters rush \u2014 unaware they've already crossed the dyke"}),"\n",(0,s.jsxs)(n.p,{children:["Xiaoren asks the moderator \u2014 which words cannot be uttered \u2014 in the grand mansion with deep gates \u2014 what kind of tree should be planted \u2014 if one plants wrong \u2014 will one be reported to the authorities",(0,s.jsx)("br",{}),"\nMy ears have been hard of hearing all my life \u2014 can't hear the drum before the hall \u2014 blind and cannot see \u2014 the rules and squares on the pillars \u2014 I only feel the road ahead is dark \u2014 as if there are knives and axes",(0,s.jsx)("br",{}),"\nIn short, for us common folk \u2014 left or right, it's all suffering"]}),"\n",(0,s.jsx)(n.p,{children:"Colors and claws \u2014 all spoken for the blind \u2014 one should speak in one's native tongue \u2014 slavishly copying the ancients is mere parrotry"}),"\n",(0,s.jsx)(n.p,{children:"Xiaoren doesn't even understand \u2014 who he himself is \u2014 whoever claims to know you \u2014 don't pretend to be a prophet"}),"\n",(0,s.jsxs)(n.p,{children:["I've been provoking all along \u2014 how can you not know? \u2014 Coming and going stark naked \u2014 disguises have always been few",(0,s.jsx)("br",{}),"\nWhen the mind gives rise to demons, demons arise of themselves \u2014 when will it ever end? \u2014 Looking ahead at the road to the Yellow Springs \u2014 how many seconds remain?"]}),"\n",(0,s.jsxs)(n.p,{children:["When feelings come, excitement rises of itself \u2014 in the end it won't fizzle out \u2014 old white-haired men of the world \u2014 how is that matter ever any less?",(0,s.jsx)("br",{}),"\nJust afraid of having one eye \u2014 that only sees the surface \u2014 in the end, dream upon dream \u2014 a thousand lifetimes still plagued with worries"]}),"\n",(0,s.jsxs)(n.p,{children:["Heaven and earth are clean everywhere \u2014 where does filth come from? \u2014 All things are equal without difference \u2014 only the mediocre cling to love",(0,s.jsx)("br",{}),"\nThe lotus boat is empty and void \u2014 it can carry anything \u2014 recognize the treasure within your robe \u2014 don't be obstructed by words"]}),"\n",(0,s.jsxs)(n.p,{children:["Discussing matters without being stuck on the matter \u2014 yes is still yes \u2014 stuck on the matter without discussing it \u2014 just treat it as a game",(0,s.jsx)("br",{}),"\nThe lofty pavilion doesn't find itself filthy \u2014 the latrine doesn't pinch its nose \u2014 heaven and earth are spacious everywhere \u2014 where can one not sleep?"]}),"\n",(0,s.jsx)(n.p,{children:"Don't cling to even a single word \u2014 who cares about A B C \u2014 when mind is empty, the scene is empty of itself \u2014 who keeps getting G'd?"}),"\n",(0,s.jsx)(n.p,{children:"Without spear and without head \u2014 the mediocre oppose themselves \u2014 heaven and earth are but floating bubbles \u2014 nobody is worthy"}),"\n",(0,s.jsx)(n.p,{children:"Under the First Emperor's blade, tens of thousands of corpses \u2014 Li Si carved inscriptions on stone \u2014 it's just that the book-burning was too soft-hearted \u2014 later generations of the poetry forum surpassed their predecessors"}),"\n",(0,s.jsx)(n.p,{children:"Under the First Emperor's blade, a ghost \u2014 on the internet, a person beside the axe \u2014 don't blame it on the red dust within \u2014 there are so many ass-kissing ministers nowadays"}),"\n",(0,s.jsx)(n.p,{children:"Invited to leave, then invited back \u2014 though it's no golden terrace \u2014 only fear there's a ghost at the door \u2014 not letting anyone in"}),"\n",(0,s.jsx)(n.p,{children:"The four great elements are empty, empty \u2014 have something to say, just write \u2014 the twenty-first century \u2014 how can there still be widows?"}),"\n",(0,s.jsx)(n.p,{children:"The Human King and the Demon King \u2014 who among them lacks logic? \u2014 Why must one always be right? \u2014 Nobody is going to get worked up over you"}),"\n",(0,s.jsx)(n.p,{children:"The Human King and the Demon King \u2014 who among them doesn't serve the people? \u2014 It's just that when it's time to pay the bill \u2014 they want copper and they want silver"}),"\n",(0,s.jsx)(n.p,{children:'The character for "official" has two mouths \u2014 always making up stories \u2014 no wonder the reports are full of \u2014 nothing but fake numbers'}),"\n",(0,s.jsx)(n.p,{children:"Warning after warning \u2014 handing out big hats at the sight of a head \u2014 no one is worth cursing \u2014 not even a bandit"}),"\n",(0,s.jsx)(n.p,{children:"The magistrate can burn all he wants \u2014 but the commoners can't even light a candle? \u2014 if you want to point out others' faults \u2014 you yourself must first be capable"}),"\n",(0,s.jsx)(n.p,{children:"Open schemes and hidden schemes \u2014 no reasons needed \u2014 as long as the officials have mouths \u2014 the Yellow River can flow westward"}),"\n",(0,s.jsx)(n.p,{children:"Old madams and old madams \u2014 as long as they get together \u2014 don't step outside this door \u2014 pound the rice to your hearts' content"}),"\n",(0,s.jsx)(n.p,{children:"Thanking with mouth and thanking with heart \u2014 the bond forever free of fraud \u2014 this plot of land before the door \u2014 next year its price will rise"}),"\n",(0,s.jsx)(n.p,{children:"A wax-tipped spear needs to see fire \u2014 it's not just a silver-plated look \u2014 the latest high technology \u2014 no need to load the chamber"}),"\n",(0,s.jsx)(n.p,{children:"Moderator and Xiaoren \u2014 naturally quite different \u2014 the moderator wears a feathered cap \u2014 Xiaoren doesn't have a copper coin"}),"\n",(0,s.jsx)(n.p,{children:"Hands err but the heart does not \u2014 foolish the person, more foolish the love \u2014 next year when flowers send their word \u2014 together we'll plant bamboo branches"}),"\n",(0,s.jsx)(n.p,{children:"Games in the mirror raise dust indeed \u2014 why take everything so seriously? \u2014 the snow-print remains briefly, the wild goose long gone \u2014 don't look at phantom shadows and add needless anger"}),"\n",(0,s.jsx)(n.p,{children:"Pick up the brush and stand a thousand words \u2014 why need a draft in the belly? \u2014 poetry is also prose \u2014 don't draw a circle and imprison yourself"}),"\n",(0,s.jsx)(n.p,{children:"The prophet dies before his time \u2014 a hundred generations leave their branches \u2014 fooling people and fooling ghosts \u2014 everywhere playing at miracles"}),"\n",(0,s.jsx)(n.p,{children:"Forced to change one's name \u2014 why are heaven and earth so blind? \u2014 smash the sun and moon to pieces \u2014 and heaven and earth will find their own peace"})]})}function c(e={}){let{wrapper:n}={...(0,a.R)(),...e.components};return n?(0,s.jsx)(n,{...e,children:(0,s.jsx)(d,{...e})}):d(e)}},28453(e,n,t){t.d(n,{R:()=>r,x:()=>i});var o=t(96540);let s={},a=o.createContext(s);function r(e){let n=o.useContext(a);return o.useMemo(function(){return"function"==typeof e?e(n):{...n,...e}},[n,e])}function i(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(s):e.components||s:r(e.components),o.createElement(a.Provider,{value:n},e.children)}}}]);